from __future__ import annotations

from datetime import date, datetime, time
from pathlib import Path
from zoneinfo import ZoneInfo

import frontmatter

from .models import Draft, DraftMeta, Slot
from .paths import repo_root

IST = ZoneInfo("Asia/Kolkata")
SLOT_TIMES = {"a": time(9, 30), "b": time(19, 0)}


def drafts_dir() -> Path:
    path = repo_root() / "drafts"
    path.mkdir(parents=True, exist_ok=True)
    return path


def draft_path(day: date, slot: Slot) -> Path:
    return drafts_dir() / f"{day.isoformat()}-{slot}.md"


def default_scheduled_at(day: date, slot: Slot) -> datetime:
    return datetime.combine(day, SLOT_TIMES[slot], tzinfo=IST)


def load_draft(path: Path) -> Draft:
    post = frontmatter.load(path)
    meta = DraftMeta.model_validate(post.metadata)
    return Draft(path=str(path), meta=meta, body=str(post.content).strip() + "\n")


def save_draft(draft: Draft) -> Path:
    path = Path(draft.path)
    path.parent.mkdir(parents=True, exist_ok=True)
    post = frontmatter.Post(draft.body.strip() + "\n", **draft.meta.model_dump(mode="json"))
    path.write_text(frontmatter.dumps(post) + "\n", encoding="utf-8")
    return path


def list_drafts(*, statuses: set[str] | None = None) -> list[Draft]:
    items: list[Draft] = []
    for path in sorted(drafts_dir().glob("*.md")):
        if path.name.lower() == "readme.md":
            continue
        try:
            draft = load_draft(path)
        except Exception:
            continue
        if statuses and draft.meta.status not in statuses:
            continue
        items.append(draft)
    return items
